import{z as n,x as l,o as t,c as p,q as o,j as B,D as A,d as e,s,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"APT 作为均衡","description":"","frontmatter":{"title":"APT 作为均衡","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/apt-as-equilibrium.md","filePath":"econ/apt-as-equilibrium.md","lastUpdated":1791063341000}'),m={name:"econ/apt-as-equilibrium.md"};function d(h,a,D,u,C,c){const r=l("Mermaid");return t(),p("div",null,[a[2]||(a[2]=o('<h1 id="apt-作为均衡" tabindex="-1">APT 作为均衡 <a class="header-anchor" href="#apt-作为均衡" aria-label="Permalink to &quot;APT 作为均衡&quot;">​</a></h1><div class="epigraph"><p>若收益由少数共同因子加上可分散残差生成，无套利要求期望收益近似落在因子载荷的线性定价平面上。</p><footer>—— Ross, The Arbitrage Theory of Capital Asset Pricing, Journal of Economic Theory 1976</footer></div><p><a href="/econ/capm-theory">上一课</a>在均值–方差与同质预期下把定价核收成与市场回报线性。本课缺口不是再估一条市场回归，而是：<strong>去掉均值–方差偏好</strong>之后，无套利本身能否给出截面上的线性定价。Ross（1976）的回答是均衡陈述：因子结构加可分散残差 ⇒ 期望收益对载荷近似线性。主成分、风格因子、横截面 \\(t\\) 统计不在本栏，见量化栏 <a href="/quant/stat-risk-pca">统计风险模型 PCA</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CAPM 把「被定价的风险」钉成对市场组合的协方差，因为切点出清成了市场。若投资者并不只关心均值与方差，市场组合不必有效，\\(m\\) 也不必与 \\(R_m\\) 线性。还剩下什么？Ross 假定收益有因子生成过程</p> \\[R_i=\\mathrm{E}[R_i]+\\beta_i^\\top f+\\varepsilon_i, \\]<p>其中 \\(f\\) 是均值为零的共同冲击，\\(\\varepsilon_i\\) 在充分分散的组合里可以忽略。缺口是：在这种结构下，若 \\(\\mathrm{E}[R_i]\\) 不是载荷的线性函数，能否构造出风险任意小、超额任意大的套利。能，则均衡（无套利）要求线性定价。这不是「对收益矩阵做 PCA 得到因子」。</p><p><span class="marginnote">近似 APT：残差不必严格正交，只要特异风险可分散，定价误差在大经济里一致地变小。Chamberlain–Rothschild（1983）把近似因子结构写成特征值条件，仍是理论，不是估 \\(K\\)。</span></p><p><span class="marginnote">「因子载荷」\\(\\beta_i\\) 可以翻译成资产的风险坐标：比如 \\(\\beta_i=(1.2,\\,0.3)\\) 表示大盘类共同冲击每动 1 个单位，这只资产平均跟着动 1.2 个单位，利率类冲击每动 1 单位它动 0.3 单位。APT 说的就是：期望收益只由这组坐标决定，与资产叫什么名字无关。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>无套利在这里是组合层面的：存在充分分散的零净投资组合，使因子暴露为零、残差风险趋于零，则其期望超额必须趋于零，否则可无限放大。于是存在因子价格 \\(\\lambda\\)（及零 beta 回报 \\(\\lambda_0\\)）使得</p> \\[\\mathrm{E}[R_i]\\approx\\lambda_0+\\beta_i^\\top\\lambda. \\]<p>这与 SDF 语言一致：若 \\(m\\) 落在因子张成的空间里（或对其投影足够），则只有因子协方差被定价。市场组合可以是因子之一，但不必是唯一因子——APT 不把切点定理再证一遍。</p>',13)),(t(),B(i,null,{default:A(()=>[s(r,{id:"mermaid-33",class:"mermaid",graph:"flowchart%20TD%0A%20%20GEN%5B%22%E5%9B%A0%E5%AD%90%E7%94%9F%E6%88%90%E8%BF%87%E7%A8%8B%22%5D%20--%3E%20DIV%5B%22%E6%AE%8B%E5%B7%AE%E5%8F%AF%E5%88%86%E6%95%A3%22%5D%0A%20%20DIV%20--%3E%20NA%5B%22%E6%97%A0%E5%A5%97%E5%88%A9%22%5D%0A%20%20NA%20--%3E%20LIN%5B%22E%5BR%5D%20%E5%AF%B9%E8%BD%BD%E8%8D%B7%E8%BF%91%E4%BC%BC%E7%BA%BF%E6%80%A7%22%5D%0A%20%20LIN%20--%3E%20NOT%5B%22%E4%B8%8D%E6%98%AF%20PCA%20%E4%BC%B0%E5%9B%A0%E5%AD%90%22%5D%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"Connor 一类竞争均衡版本把「无套利」换成大经济里的价格接受者；线性关系变成精确的一阶条件。本课采用 Ross 最瘦的无套利陈述，不把存在性再做成角谷习题。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[e("机制是分散化切断特异风险与期望收益的联系。一个人可以做多被低估、做空被高估、对冲掉 \\(f\\)，剩下的 \\(\\varepsilon\\) 在 \\(N\\to\\infty\\) 时进组合方差的速度不够快——若定价误差不消失，就有免费午餐。因此被定价的是"),E("strong",null,"对共同因子的暴露"),e("，不是名字叫「市场」的某一个指数。因子在理论里是收益生成过程的原语；它们是什么宏观变量、要不要可交易，是后话，不是 1976 年的定理。")],-1)),a[6]||(a[6]=E("p",null,"上一张图给出结论链条；这一张拆开无套利本身的操作：定价偏离平面时，套利组合是怎么一步步搭出来、又为什么迫使价格回去。",-1)),(t(),B(i,null,{default:A(()=>[s(r,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEV%5B%22%E6%9F%90%E8%B5%84%E4%BA%A7%E6%9C%9F%E6%9C%9B%E6%94%B6%E7%9B%8A%E5%81%8F%E7%A6%BB%E5%AE%9A%E4%BB%B7%E5%B9%B3%E9%9D%A2%22%5D%20--%3E%20LONG%5B%22%E5%81%9A%E5%A4%9A%E8%A2%AB%E4%BD%8E%E4%BC%B0%E7%9A%84%E4%B8%80%E7%AF%AE%E5%AD%90%22%5D%0A%20%20DEV%20--%3E%20SHORT%5B%22%E5%81%9A%E7%A9%BA%E8%A2%AB%E9%AB%98%E4%BC%B0%E7%9A%84%E4%B8%80%E7%AF%AE%E5%AD%90%22%5D%0A%20%20LONG%20--%3E%20HEDGE%5B%22%E4%B8%A4%E8%BE%B9%E5%9B%A0%E5%AD%90%E8%BD%BD%E8%8D%B7%E5%AF%B9%E9%BD%90%EF%BC%8C%E5%87%80%E5%9B%A0%E5%AD%90%E6%9A%B4%E9%9C%B2%E4%B8%BA%E9%9B%B6%22%5D%0A%20%20SHORT%20--%3E%20HEDGE%0A%20%20HEDGE%20--%3E%20DIV%5B%22%E5%88%86%E6%95%A3%E5%88%B0%E5%A4%A7%E9%87%8F%E8%B5%84%E4%BA%A7%EF%BC%8C%E6%AE%8B%E5%B7%AE%E9%A3%8E%E9%99%A9%E8%B6%8B%E4%BA%8E%E9%9B%B6%22%5D%0A%20%20DIV%20--%3E%20LUNCH%5B%22%E6%9C%9F%E6%9C%9B%E8%B6%85%E9%A2%9D%E5%A4%A7%E4%BA%8E%E9%9B%B6%E3%80%81%E9%A3%8E%E9%99%A9%E8%BF%91%E9%9B%B6%E7%9A%84%E7%BB%84%E5%90%88%22%5D%0A%20%20LUNCH%20--%3E%20SCALE%5B%22%E6%97%A0%E9%99%90%E6%94%BE%E5%A4%A7%E4%BB%93%E4%BD%8D%EF%BC%8C%E5%A5%97%E5%88%A9%E5%8A%9B%E9%87%8F%E6%8A%8A%E4%BB%B7%E6%A0%BC%E6%8E%A8%E5%9B%9E%E5%B9%B3%E9%9D%A2%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">数字实例：若 A、B 两个分散化组合因子载荷完全相同，A 的期望收益 8%、B 只有 6%，则「买 A 卖 B」的零净投资组合每年稳赚约 2 个百分点且不承担因子风险——放大到 1 亿元敞口就是约 200 万元。只要这种机会存在，竞争会让价差收敛。</span></p><h3 id="本栏停在无套利平面-实证换栏" tabindex="-1">本栏停在无套利平面，实证换栏 <a class="header-anchor" href="#本栏停在无套利平面-实证换栏" aria-label="Permalink to &quot;本栏停在无套利平面，实证换栏&quot;">​</a></h3><p>把 \\(f\\) 换成样本主成分、行业收益或 Fama–French 风格，再做时间序列 \\(\\alpha\\)，对象已经变成可交易（或统计）因子模型。那是量化栏的风险模型，不是把 Ross 改写成估特征值。链接足够：<a href="/quant/stat-risk-pca">统计风险模型 PCA</a>；市场因子检验仍见 <a href="/quant/capm">CAPM 与市场因子</a>。本课不排序组合、不写 GRS、不选 \\(K\\)。</p><p><span class="marginnote">Chen–Roll–Ross 的宏观因子、Connor–Korajczyk 的渐近主成分，都是对这条线性关系的实施与估计。失败方式（载荷不稳、因子旋转、残差仍有定价）属于估计对象，不是 APT 作为均衡被终审。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在本栏宣布「APT 比 CAPM 更真，因为因子更多」。多因子是更富的 \\(m\\) 投影，仍需要无套利加可分散残差；没有因子结构，无套利只回到一般的 \\(0=\\mathrm{E}[m R^e]\\)。也不要把 APT 写成 EMH：线性定价是对期望的形状限制，信息公开速度是另一句话。</p><p>下一课离开截面因子，把同一套折现用到不同到期的无违约债券：<a href="/econ/eh-term-structure">期限结构预期假说</a>。</p><p>不要把限价簿上的共同冲击（拥挤、流动性枯竭）写进本课当「APT 因子」。簿是协议，见量化栏；本栏的 \\(f\\) 没有队列。</p><p>精确 APT 需要残差在分散后消失。有界非对角的特异协方差只给近似。有套利限制（卖空、资金）时，定价误差可以不消失——那是摩擦，不是把 1976 从主干删掉。</p><p>因子必须是共同冲击。把每个行业虚拟变量都叫因子，而不问残差能否分散，线性关系可以是会计恒等而不是无套利。Ross 的锋芒在可分散 \\(\\varepsilon\\)，不在给 \\(f\\) 起宏观名字。</p><p><span class="marginnote">常见误区：以为 APT 是一套「挑因子赚钱」的选股方法。实际上它是一条定价约束——若收益确有共同因子结构，期望收益就必须近似排成载荷的线性函数；至于因子该叫通胀、久期还是动量，以及怎么从数据里估出来，定理本身一个字都没说。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>因子结构 + 可分散残差 + 无套利 ⇒ 期望收益对载荷近似线性。</li><li>这是均衡陈述，不依赖均值–方差切点，也不把市场规定为唯一因子。</li><li>本栏不估主成分、不跑风格横截面；实证见量化栏 PCA。</li><li>出处：Ross, <em>Journal of Economic Theory</em> 1976。</li></ul>',13))])}const P=n(m,[["render",d]]);export{T as __pageData,P as default};
